    describe('Fluent => XML => Fluent', () => {
        test('roles round-trips correctly', async () => {
            const test = new FluentXmlFluentTest(
                ctx.createProject({ config: { scope: 'x_test', scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
            )
            const adminId = test.addCoalesceId('sys_user_role', { name: 'x_test.admin' })
            const managerId = test.addCoalesceId('sys_user_role', { name: 'x_test.manager' })
            const m2mId = test.addCoalesceId('sys_user_role_contains', { role: adminId, contains: managerId })

            test.addExpectedXmlFileNames(
                `sys_user_role_${adminId}.xml`,
                `sys_user_role_${managerId}.xml`,
                `sys_user_role_contains_${m2mId}.xml`
            )

            test.addFluentFragment(`import { Role } from '@servicenow/sdk/core'

const prefix = 'x_test'
const manager = 'manager'
const managerRole = Role({
    name: \`\${prefix}.\${manager}\`,
})

Role({
    name: \`\${prefix}.admin\`,
    containsRoles: [managerRole],
})
`)
            await test.verify()
        })

        test('Roles with snake_case gets updated to camelCase on round-trip', async () => {
            const project = createProject({ rootDir: __dirname })
            project.registerCoalesceId('sys_user_role_contains', {
                role: project.registerCoalesceId('sys_user_role', { name: 'x_test.admin' }),
                contains: project.registerCoalesceId('sys_user_role', { name: 'x_test.manager' }),
            })

            const roleFile = project.addFile({
                path: 'roles.now.ts',
                content: `import { Role } from '@servicenow/sdk/core'

const prefix = 'x_test'
const manager = 'manager'
const managerRole = Role({
    name: \`\${prefix}.\${manager}\`,
})

Role({
    name: \`\${prefix}.admin\`,
    contains_roles: [managerRole],
})`,
            })

            const xmlOutputs = await roleFile.getOutput()
            const { changedFiles } = await project.transform(xmlOutputs)
            expect(await project.getDiagnostics()).toHaveLength(0)
            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('roles.now.ts')
            expect(changedFiles[0].getContent()).toBe(`import { Role } from '@servicenow/sdk/core'

const prefix = 'x_test'
const manager = 'manager'
const managerRole = Role({
    name: \`\${prefix}.\${manager}\`,
})

Role({
    name: \`\${prefix}.admin\`,
    containsRoles: [managerRole],
})
`)
        })
    })

